contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount, uint v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount >= 1);
        require(v >= 1 && v <= amount);
        c.sendMoney(address(c), amount, ""); if (__ESBMC_reverted()) return;
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        uint thisBefore = address(this).balance;
        c.withdraw(v); if (__ESBMC_reverted()) return;
        assert(address(c).balance == balBefore - v
            && address(this).balance == thisBefore + v
            && c.depositsCount() == countBefore);
    }
    receive() external payable {}
}

