// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount, uint256 v) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount >= 1);
        vm.assume(v >= 1 && v <= amount);
        try c.sendMoney(address(c), amount, "") {} catch { return; }
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        uint balBefore = address(c).balance;
        uint thisBefore = address(this).balance;
        try c.withdraw(v) {} catch { return; }
        assertTrue(address(c).balance == balBefore - v
            && address(this).balance == thisBefore + v
            && c.depositsCount() == countBefore);
    }

    function testFuzz_run(uint256 amount, uint256 v) public {
        _run(amount, v);
    }

    receive() external payable {}
}
